@prefix ada: <https://ada.astromat.org/metadata/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a ada:NanoSIMSTabular ;
                    ada:isotopeAnalyzed "12C",
                        "13C",
                        "28Si",
                        "29Si" ;
                    ada:phaseAnalyzed "presolar SiC",
                        "presolar graphite" ] ;
            sh:resultMessage "NanoSIMS detail nodes must declare ada:componentType." ;
            sh:resultPath ada:componentType ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:maxCount 1 ;
                    sh:message "NanoSIMS detail nodes must declare ada:componentType." ;
                    sh:minCount 1 ;
                    sh:path ada:componentType ] ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .
